library(shiny)
library(shinydashboard)
library(lpSolve)
library(DT)
library(shinyWidgets)
library(lubridate)

# UIの設定
ui <- dashboardPage(
  dashboardHeader(title = "当直表Pro (軽量版)"),
  dashboardSidebar(
    sidebarMenu(
      menuItem("基本設定", tabName = "settings", icon = icon("cog")),
      menuItem("スタッフ入力", tabName = "user_input", icon = icon("user-edit")),
      menuItem("当直表の生成", tabName = "generate", icon = icon("calendar-check"))
    )
  ),
  dashboardBody(
    tags$style(HTML("
      .calendar-table { width: 100%; table-layout: fixed; background-color: white; }
      .calendar-table th { text-align: center; background-color: #f4f4f4; padding: 10px; border: 1px solid #ddd; }
      .calendar-table td { height: 100px; vertical-align: top; border: 1px solid #ddd; padding: 5px; }
      .sun { color: red; background-color: #fff0f0; }
      .sat { color: blue; background-color: #f0f0ff; }
      .day-num { font-weight: bold; font-size: 1.1em; }
      .duty-name { display: block; margin-top: 10px; text-align: center; font-size: 1.3em; color: #2c3e50; font-weight: bold; }
    ")),
    tabItems(
      tabItem(tabName = "settings",
              box(title = "カレンダー設定", width = 12,
                  airMonthpickerInput("start_month", "対象月を選択:", value = Sys.Date(), language = "ja"),
                  numericInput("n_days", "対象日数:", 31, min = 1, max = 31),
                  airDatepickerInput("holidays", "祝日を選択:", multiple = TRUE, language = "ja"),
                  textInput("staff_list", "スタッフ名（カンマ区切り）:", "医師A, 医師B, 医師C, 医師D, 医師E"),
                  actionButton("update_staff", "設定を更新", class = "btn-primary")
              )
      ),
      tabItem(tabName = "user_input",
              fluidRow(
                column(width = 5,
                       uiOutput("select_staff_ui"),
                       hr(),
                       numericInput("pref_weekday", "平日当直の希望回数:", 4, min = 0),
                       checkboxInput("want_weekend", "土日祝の当直を希望する", value = TRUE),
                       airDatepickerInput("ng_days", "当直NG日:", multiple = TRUE, language = "ja"),
                       airDatepickerInput("gaikin_days", "外勤日:", multiple = TRUE, language = "ja"),
                       airDatepickerInput("gaikin_tochoku_days", "外勤当直日 (翌日不可):", multiple = TRUE, language = "ja"),
                       actionButton("save_input", "この人の内容を保存", class = "btn-success", icon = icon("save"))
                ),
                column(width = 7,
                       box(title = "現在の保存済みデータ", width = 12, DTOutput("input_summary"))
                )
              )
      ),
      tabItem(tabName = "generate",
              actionButton("run_calc", "当直表を作成する", icon = icon("play"), class = "btn-block btn-lg btn-danger"),
              hr(),
              tabBox(title = "結果表示", width = 12,
                     tabPanel("カレンダー表示", htmlOutput("calendar_view")),
                     tabPanel("集計結果", tableOutput("count_summary"))
              )
      )
    )
  )
)

server <- function(input, output, session) {
  vals <- reactiveValues(
    staff = c("医師A", "医師B", "医師C", "医師D", "医師E"),
    data = data.frame(),
    result = NULL
  )
  
  init_data <- function(staff_vector) {
    data.frame(
      名前 = staff_vector, 平日希望 = 4, 休日希望 = TRUE,
      NG日 = "", 外勤日 = "", 外勤当直日 = "", stringsAsFactors = FALSE
    )
  }
  
  observeEvent(input$update_staff, {
    vals$staff <- trimws(unlist(strsplit(input$staff_list, ",")))
    vals$data <- init_data(vals$staff)
  })
  
  isolate({ vals$data <- init_data(vals$staff) })
  
  output$select_staff_ui <- renderUI({ selectInput("current_staff", "スタッフを選択:", choices = vals$staff) })
  
  observeEvent(input$current_staff, {
    user_row <- vals$data[vals$data$名前 == input$current_staff, ]
    if(nrow(user_row) > 0) {
      updateNumericInput(session, "pref_weekday", value = user_row$平日希望)
      updateCheckboxInput(session, "want_weekend", value = user_row$休日希望)
      
      refresh_cal <- function(inputId, saved_str) {
        if (is.null(saved_str) || saved_str == "" || is.na(saved_str)) {
          updateAirDateInput(session, inputId, clear = TRUE)
        } else {
          days <- as.numeric(unlist(strsplit(as.character(saved_str), ",")))
          target_dates <- as.Date(paste0(format(input$start_month, "%Y-%m-"), sprintf("%02d", days)))
          updateAirDateInput(session, inputId, value = target_dates)
        }
      }
      refresh_cal("ng_days", user_row$NG日)
      refresh_cal("gaikin_days", user_row$外勤日)
      refresh_cal("gaikin_tochoku_days", user_row$外勤当直日)
    }
  })
  
  observeEvent(input$save_input, {
    format_days <- function(d) if (is.null(d)) return("") else paste(sort(as.numeric(format(d, "%d"))), collapse = ", ")
    vals$data[vals$data$名前 == input$current_staff, ] <- list(
      input$current_staff, input$pref_weekday, input$want_weekend,
      format_days(input$ng_days), format_days(input$gaikin_days), format_days(input$gaikin_tochoku_days)
    )
    showNotification("保存しました")
  })
  
  output$input_summary <- renderDT({ datatable(vals$data, options = list(dom = 't')) })
  
  observeEvent(input$run_calc, {
    n_staff <- length(vals$staff); n_days <- input$n_days; num_vars <- n_staff * n_days
    str_to_vec <- function(s) if (s == "" || is.na(s)) return(numeric(0)) else as.numeric(unlist(strsplit(as.character(s), ",")))
    
    start_date <- as.Date(paste0(format(input$start_month, "%Y-%m-01")))
    all_dates <- seq(start_date, length.out = n_days, by = "day")
    holidays <- if(!is.null(input$holidays)) as.numeric(format(input$holidays, "%d")) else c()
    is_weekend_day <- (wday(all_dates) %in% c(1, 7)) | (day(all_dates) %in% holidays)
    
    weekday_indices <- which(!is_weekend_day); weekend_indices <- which(is_weekend_day)
    target_weekend_count <- length(weekend_indices) / max(1, sum(vals$data$休日希望))
    
    obj <- rep(1, num_vars) + runif(num_vars, 0, 0.1)
    con <- matrix(0, nrow = 0, ncol = num_vars); dir <- c(); rhs <- c()
    
    for (j in 1:n_days) {
      row <- rep(0, num_vars); row[seq(j, by = n_days, length.out = n_staff)] <- 1
      con <- rbind(con, row); dir <- c(dir, "="); rhs <- c(rhs, 1)
    }
    
    for (i in 1:n_staff) {
      user_row <- vals$data[i, ]
      for (d in c(str_to_vec(user_row$NG日), str_to_vec(user_row$外勤日))) {
        if (!is.na(d) && d <= n_days) {
          row <- rep(0, num_vars); row[(i-1)*n_days + d] <- 1
          con <- rbind(con, row); dir <- c(dir, "="); rhs <- c(rhs, 0)
        }
      }
      for (d in str_to_vec(user_row$外勤当直日)) {
        if (!is.na(d) && (d+1) <= n_days) {
          row <- rep(0, num_vars); row[(i-1)*n_days + d + 1] <- 1
          con <- rbind(con, row); dir <- c(dir, "="); rhs <- c(rhs, 0)
        }
      }
      for (d in 1:(n_days-1)) {
        row <- rep(0, num_vars); row[(i-1)*n_days + d] <- 1; row[(i-1)*n_days + d + 1] <- 1
        con <- rbind(con, row); dir <- c(dir, "<="); rhs <- c(rhs, 1)
      }
      row_wd <- rep(0, num_vars); row_wd[(i-1)*n_days + weekday_indices] <- 1
      con <- rbind(con, row_wd); dir <- c(dir, ">="); rhs <- c(rhs, max(0, user_row$平日希望 - 1))
      con <- rbind(con, row_wd); dir <- c(dir, "<="); rhs <- c(rhs, user_row$平日希望 + 1)
      
      row_we <- rep(0, num_vars); row_we[(i-1)*n_days + weekend_indices] <- 1
      if (user_row$休日希望) {
        con <- rbind(con, row_we); dir <- c(dir, ">="); rhs <- c(rhs, floor(target_weekend_count))
        con <- rbind(con, row_we); dir <- c(dir, "<="); rhs <- c(rhs, ceiling(target_weekend_count))
      } else {
        con <- rbind(con, row_we); dir <- c(dir, "="); rhs <- c(rhs, 0)
      }
    }
    
    res <- lp("min", obj, con, dir, rhs, all.bin = TRUE)
    if (res$status == 0) {
      sol <- matrix(res$solution, nrow = n_staff, byrow = TRUE)
      vals$result <- data.frame(
        日付 = all_dates, 
        当直 = apply(sol, 2, function(x) vals$staff[which(x == 1)])
      )
    } else {
      showNotification("解なし。制約を緩めてください。", type = "error")
    }
  })
  
  output$calendar_view <- renderUI({
    if (is.null(vals$result)) return("「当直表を作成する」ボタンを押してください。")
    df <- vals$result
    start_date <- df$日付[1]
    first_wday <- wday(start_date)
    grid <- c(rep(NA, first_wday - 1), 1:nrow(df))
    grid <- c(grid, rep(NA, 7 - (length(grid) %% 7)))
    cal_matrix <- matrix(grid, ncol = 7, byrow = TRUE)
    
    tags$table(class = "calendar-table",
               tags$thead(tags$tr(lapply(c("日", "月", "火", "水", "木", "金", "土"), tags$th))),
               tags$tbody(
                 apply(cal_matrix, 1, function(row_days) {
                   tags$tr(lapply(1:7, function(col_idx) {
                     d_idx <- row_days[col_idx]
                     if (is.na(d_idx)) { tags$td("") } else {
                       curr_date <- df$日付[d_idx]
                       cell_class <- if(col_idx == 1) "sun" else if(col_idx == 7) "sat" else ""
                       tags$td(class = cell_class, tags$span(class="day-num", day(curr_date)), tags$span(class="duty-name", df$当直[d_idx]))
                     }
                   }))
                 })
               )
    )
  })
  
  output$count_summary <- renderTable({
    if (is.null(vals$result)) return()
    res <- vals$result
    res$is_weekend <- ifelse(wday(res$日付) %in% c(1,7), "休日", "平日")
    as.data.frame(table(res$当直, res$is_weekend))
  })
}

shinyApp(ui, server)
